(function(root){
'use strict';
const fresh=()=>({version:1,records:{},session:null});
const normalize=(s,q={})=>{let value=String(s??'').normalize('NFKC').trim().replace(/\s+/g,' ');if(q.preservePunctuation===false)value=value.replace(/[，,。；;、]/g,'');return q.caseSensitive?value:value.toLowerCase();};
function grade(q,answer){if(q.type==='choice')return Number.isInteger(answer)&&answer===q.answer;if(q.type==='fill')return Array.isArray(answer)&&answer.length===q.answer.length&&q.answer.every((choices,i)=>choices.some(v=>normalize(v,q)===normalize(answer[i],q)));return null;}
function record(state,id,correct,answer){const old=state.records[id]||{};const streak=correct?(old.consecutiveCorrect||0)+1:0;state.records[id]={...old,attempts:(old.attempts||0)+1,correct:(old.correct||0)+(correct?1:0),wrong:(old.wrong||0)+(correct?0:1),consecutiveCorrect:streak,everWrong:!!old.everWrong||!correct,mastered:correct?streak>=2:false,favorite:!!old.favorite,lastAnswer:answer,lastCorrect:correct,updatedAt:Date.now()};return state.records[id];}
function filter(bank,state,f){return bank.filter(q=>(!f.subject||q.subject===f.subject)&&(!f.chapter||q.chapter===f.chapter)&&(!f.type||q.type===f.type)&&(!f.unanswered||!state.records[q.id]?.attempts)&&(f.pool!=='wrong'||(state.records[q.id]?.everWrong&&!state.records[q.id]?.mastered))&&(f.pool!=='history'||state.records[q.id]?.everWrong)&&(f.pool!=='mastered'||(state.records[q.id]?.everWrong&&state.records[q.id]?.mastered))&&(f.pool!=='favorites'||state.records[q.id]?.favorite));}
function validate(input,bank){if(!input||input.version!==1||!input.records||typeof input.records!=='object'||Array.isArray(input.records))throw Error('备份格式或版本不支持');const ids=new Set(bank.map(q=>q.id));const state=fresh();for(const [id,r]of Object.entries(input.records)){if(!ids.has(id))continue;if(!r||typeof r!=='object')throw Error('题目记录无效');for(const k of ['attempts','correct','wrong','consecutiveCorrect'])if(!Number.isSafeInteger(r[k]??0)||(r[k]??0)<0)throw Error('记录次数无效');if((r.correct||0)+(r.wrong||0)!==(r.attempts||0))throw Error('记录统计不一致');if((r.consecutiveCorrect||0)>(r.correct||0))throw Error('连续答对次数无效');if(r.attempts){const q=bank.find(q=>q.id===id);if(typeof r.lastCorrect!=='boolean')throw Error('最近作答结果无效');if(q.type==='choice'&&(!Number.isInteger(r.lastAnswer)||r.lastAnswer<0||r.lastAnswer>=q.options.length))throw Error('选择题答案记录无效');if(q.type==='fill'&&(!Array.isArray(r.lastAnswer)||r.lastAnswer.length!==q.answer.length||!r.lastAnswer.every(a=>typeof a==='string')))throw Error('填空题答案记录无效');if(q.type==='short'&&typeof r.lastAnswer!=='string')throw Error('简答题答案记录无效');}for(const k of ['favorite','everWrong','mastered'])if(r[k]!==undefined&&typeof r[k]!=='boolean')throw Error('记录状态无效');state.records[id]={attempts:r.attempts||0,correct:r.correct||0,wrong:r.wrong||0,consecutiveCorrect:r.consecutiveCorrect||0,favorite:!!r.favorite,everWrong:!!r.everWrong||r.wrong>0,mastered:!!r.mastered,lastCorrect:r.attempts&&typeof r.lastCorrect==='boolean'?r.lastCorrect:null,lastAnswer:!r.attempts?null:typeof r.lastAnswer==='string'?r.lastAnswer.slice(0,20000):Array.isArray(r.lastAnswer)?r.lastAnswer.map(x=>String(x).slice(0,1000)).slice(0,30):Number.isInteger(r.lastAnswer)?r.lastAnswer:null,updatedAt:Number.isSafeInteger(r.updatedAt)&&r.updatedAt>=0?r.updatedAt:0};}return state;}
function diagnose(bank,state){const rows=[];for(const q of bank){let row=rows.find(r=>r.subject===q.subject&&r.chapter===(q.chapter||'')&&r.point===q.point);if(!row){row={subject:q.subject,chapter:q.chapter||'',point:q.point,total:0,distinct:0,attempts:0,correct:0,wrong:0,repeated:0};rows.push(row)}row.total++;const r=state.records[q.id]||{};if(r.attempts){row.distinct++;row.attempts+=r.attempts;row.correct+=r.correct;row.wrong+=r.wrong;if(r.wrong>=2)row.repeated++}}return rows.map(r=>({...r,accuracy:r.attempts?Math.round(r.correct/r.attempts*100):null,status:!r.distinct?'未测':r.distinct<3?'待补测':r.correct/r.attempts<.8||r.repeated?'需巩固':'较稳'}));}
function sessionStats(session){const ids=session?.ids||[],answers=session?.answers||{};const correct=ids.filter(id=>answers[id]?.correct===true).length,wrong=ids.filter(id=>answers[id]?.correct===false).length;return {total:ids.length,correct,wrong,answered:correct+wrong,unanswered:ids.length-correct-wrong};}
function jump(session,index){if(!session||!Number.isInteger(index)||index<0||index>=session.ids.length)return false;session.index=index;return true;}
function aggregate(bank,state){return diagnose(bank,state).map(({subject,chapter,point,distinct,total,correct,wrong,repeated,status})=>({subject,chapter,point,distinct,total,correct,wrong,repeated,status}));}
function pickQuoteIndex(count,last,random=Math.random){if(!Number.isInteger(count)||count<1)return -1;if(count===1)return 0;const valid=Number.isInteger(last)&&last>=0&&last<count;const offset=Math.min((valid?count-1:count)-1,Math.max(0,Math.floor(random()*(valid?count-1:count))));return valid&&offset>=last?offset+1:offset;}
const api={fresh,normalize,grade,record,filter,validate,diagnose,sessionStats,jump,aggregate,pickQuoteIndex};if(typeof module!=='undefined')module.exports=api;else root.StudyLogic=api;
})(typeof window!=='undefined'?window:globalThis);
